function permutations(items) {
  if (items.length <= 1) {
    return [items];
  }
  var result = [];
  items.forEach(function (item, i) {
    var rest = items.slice(0, i).concat(items.slice(i + 1));
    permutations(rest).forEach(function (p) {
      result.push([item].concat(p));
    });
  });
  return result;
}

console.log(permutations([1, 2, 3]));
